"""Independent 9709 S1 representation teaching; exact checks, not automatic drawing marks."""
from fractions import Fraction as F
from statistics import median
import sympy as s
lessons,questions,models=[],[],[]
def tex(v):return s.latex(s.Rational(v.numerator,v.denominator) if isinstance(v,F) else s.sympify(v))
def math(v):return r'\('+(v if isinstance(v,str) and '\\' in v else tex(v))+r'\)'
def data(v):return ', '.join(str(a) for a in v)
def five(a):
 a=sorted(a);h=len(a)//2
 return [F(a[0]),F(median(a[:h])),F(median(a)),F(median(a[-h:])),F(a[-1])]
def stem(a,b=None,scale=1,names=('A','B'),unit=''):
 a=sorted(a);b=sorted(b) if b is not None else None
 stems=range(min(a+(b or []))//10,max(a+(b or []))//10+1)
 rows=[]
 for k in stems:
  right=' '.join(str(v%10) for v in (b if b is not None else a) if v//10==k) or '—'
  left=' '.join(str(v%10) for v in reversed(a) if v//10==k) or '—'
  rows.append('<tr>'+('<td>'+left+'</td>' if b is not None else '')+'<th scope="row">'+str(k)+'</th><td>'+right+'</td></tr>')
 head=('<th scope="col">'+names[0]+'</th>' if b is not None else '')+'<th scope="col">Stem</th><th scope="col">'+(names[1] if b is not None else 'Leaves')+'</th>'
 unit_suffix=' '+unit if unit else ''
 key=math(r'2\mid3')+' represents '+math(23*F(scale))+unit_suffix if b is None else math(r'4\mid2\mid3')+' represents '+math(24*F(scale))+unit_suffix+' for '+names[0]+' and '+math(23*F(scale))+unit_suffix+' for '+names[1]
 return '<div class="stem-leaf-scroll"><table class="stem-leaf'+(' stem-leaf-back' if b is not None else '')+'"><thead><tr>'+head+'</tr></thead><tbody>'+''.join(rows)+'</tbody></table></div><p>Key: '+key+'.</p>'

def table(head,rows):return '<table><thead><tr>'+''.join('<th scope="col">'+str(v)+'</th>' for v in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(v)+'</td>' for v in row)+'</tr>' for row in rows)+'</tbody></table>'
def picture(name,alt):return '<p><img src="/assets/original/s1-representation/'+name+'.svg" alt="'+alt+'"></p>'
def ex(title,question,solution,key):return dict(title=title,question=question,solution=solution,verification=key)
def lesson(key,title,summary,ideas,examples,before='Read scales, order numerical data and calculate with exact fractions.'):
 lessons.append(dict(key=key,id='orig_9709_s1_rep_'+key,title=title,summary=summary,objective=summary,before='<p>'+before+'</p>',ideas=ideas,method='<ol><li>Identify the variable, units and any measurement rounding.</li><li>Read the key, scale and relevant convention before calculating.</li><li>Keep repeated observations and distinguish raw values from grouped estimates.</li><li>Give a complete result and compare centre and spread in context.</li></ol>',mistakes=['A leaf is a digit, not a whole observation; read the key.', 'A histogram area, not its height alone, represents frequency.', 'Grouped quartiles are estimates; raw-data conventions must be stated.', 'A diagram alone does not determine every original observation or its exact mean.'],examples=examples))

A=[12,17,17,21,24,28,32];B=[11,16,19,23,25,31,34]
lesson('stem_reading','Data types, stem-and-leaf diagrams and quartiles',
 'Choose a suitable representation, preserve every observation and read values and quartiles from an explicit key.',
 r'''<h3>Start with the variable</h3><p>Categories such as colours are qualitative. Counts are discrete quantitative data. A measurement such as mass is continuous even when rounded before recording. A numerical label, such as a bus route number, is not a measured quantity.</p>
 <h3>A stem and a leaf form one value</h3><p>Place stems vertically in order and leaves horizontally in order. Retain repetitions and empty intermediate stems. Choose a unit and a key; the same digits can represent different scales. For example, \(2\mid3\) could mean 23 minutes or 2.3 grams.</p>'''+stem(A,unit='minutes')+r'''
 <h3>Read ordered positions, not the visual width alone</h3><p>Count every leaf. For odd n the median is observation \((n+1)/2\); for even n average the middle two. In this chapter, raw-data quartiles are medians of the two halves, excluding the overall median when n is odd. State this convention when another method is possible.</p>\[\mathrm{IQR}=Q_3-Q_1.\]
 <h3>A representation has a purpose</h3><p>A stem diagram preserves individual small-sample values; a histogram summarises a grouped distribution. A truncated bar-chart baseline can exaggerate a comparison. Choose a diagram that answers the question, and explain what information it retains or loses.</p>''',[
 ex('Preserve both copies of a repeated value','<p>Display these durations in minutes: '+data(A)+'. Include a key.</p>',stem(A,unit='minutes')+'<p>There are seven leaves, including two copies of 17. The rows represent equal-width tens classes.</p>','REP-STEM'),
 ex('Read the measurement unit, not just the digits',r'<p>A key says \(4\mid7\) represents 4.7 g. Interpret \(6\mid2\) and \(10\mid5\).</p>',r'<p>The values are 6.2 g and 10.5 g. The stem holds all digits before the tenths leaf; it is not restricted to one digit.</p>','REP-KEY'),
 ex('Find quartiles from the ordered positions','<p>Find the median and IQR of '+data(A)+'. Exclude the overall median when splitting the halves.</p>',r'<p>The middle observation is 21. The lower half is 12, 17, 17 and the upper half is 24, 28, 32.</p>\[Q_1=17,\quad Q_2=21,\quad Q_3=28,\quad\mathrm{IQR}=11.\]','REP-QUARTILES'),
 ex('A count and a rounded measurement differ',r'<p>A survey records the number of journeys and a parcel mass to the nearest gram. Classify the underlying variables.</p>',r'<p>The journey count is discrete quantitative data. The mass is continuous quantitative data; rounding changes the recorded precision, not the underlying type.</p>','REP-TYPES')])

C=[12,14,18,21,24,26,29]
lesson('stem_comparison','Back-to-back diagrams, comparisons and missing values',
 'Read mirrored leaves correctly and combine numerical comparisons with the meaning of the variable.',
 r'''<h3>Both samples share the stems</h3><p>On the right, values increase away from the stem to the right. On the left, the smallest leaf is nearest the stem, so the displayed row descends from left to right. Each side must retain its own repetitions and sample size. Give a two-sided key.</p>'''+stem(C,B,names=('Route A','Route B'),unit='minutes')+r'''
 <h3>Compare a centre and a spread</h3><p>Name the samples, statistic and context. A lower median completion time means a typical job took less time; a smaller IQR means the middle half was more consistent. A smaller median does not imply smaller spread.</p>
 <h3>Missing observations use the right total</h3>\[\text{sum}=n\bar{x}.\]<p>After adding a value, increase n as well as the sum. When the task supplies summary statistics for two samples, reconstruct totals before combining them:</p>\[\sum x^2=n(\sigma^2+\bar{x}^{\,2}),\qquad\sigma^2=\frac{\sum x^2}{n}-\bar{x}^{\,2}.\]<p>These are descriptive statistics with divisor n. Some written problems use mean/SD material from the next two book chapters; they are labelled as mixed-topic practice.</p>''',[
 ex('Read the two sides in opposite directions','<p>Interpret the back-to-back diagram and compare the routes.</p>'+stem(C,B,names=('Route A','Route B'),unit='minutes'),r'<p>Route A has median 21 and IQR 12 minutes. Route B has median 23 and IQR 15 minutes. A typically took less time and its middle half was less spread out. The left rows are read from the stem outwards, not as ascending left-to-right rows.</p>','REP-BACK'),
 ex('Update the count before finding a missing value',r'<p>Four values are 7, 9, 10 and 14. After one more value is included, the mean is 11. Find it.</p>',r'\[x=5(11)-(7+9+10+14)=15.\]<p>The final total contains five observations, not four.</p>','REP-MISSING-MEAN'),
 ex('Equal IQR does not imply equal range',r'<p>A has five-number summary \((2,6,10,14,40)\); B has \((4,7,12,15,25)\). Compare centre, IQR and range.</p>',r'<p>A has a lower median, 10 rather than 12. Both IQRs are 8, so the middle halves have equal spread. Their ranges are 38 and 21; A has more extreme overall spread. These comparisons do not determine their exact means.</p>','REP-COMPARE'),
 ex('Combine totals, not standard deviations',r'<p>A sample of 3 has mean 10 and population SD 2; another of 2 has mean 15 and population SD 3. Find the combined mean and variance.</p>',r'\[\sum x=3(10)+2(15)=60,\quad\sum x^2=3(104)+2(234)=780.\]\[\bar{x}=12,\qquad\sigma^2=\frac{780}{5}-12^2=12.\]<p>The SDs themselves are not averaged.</p>','REP-POOLED')])

lesson('histograms','Histograms, class boundaries and grouped estimates',
 'Use bar area as frequency, respect unequal class widths and distinguish exact records from midpoint estimates.',
 r'''<h3>Frequency is proportional to bar area</h3>\[\text{frequency density}=\frac{\text{frequency}}{\text{class width}}.\]<p>A class twice as wide need not have twice the height. Adjacent continuous classes touch. Label both axes and show the density scale; the tallest bar need not be the most frequent class.</p>'''+picture('histogram','Unequal class widths with frequency-density heights')+r'''
 <h3>Rounding determines continuous boundaries</h3><p>Values recorded to the nearest unit from 20 through 29 occupy \([19.5,29.5)\) under the stated half-up rounding convention. Values recorded to the nearest tenth need a half-tenth adjustment, not a half-unit adjustment.</p>
 <h3>A physical height is not yet a frequency</h3><p>If one vertical centimetre represents k density units, multiply the physical height by k, then multiply by class width. Keep horizontal and vertical scale factors separate.</p>
 <h3>Midpoints give a model, not recovered raw data</h3>\[\bar{x}\approx\frac{\sum fm}{\sum f},\qquad\sigma\approx\sqrt{\frac{\sum fm^2}{\sum f}-\bar{x}^{\,2}}.\]<p>Here m is a class midpoint. The results are estimates because the individual positions inside each class are unknown. Correcting a raw observation within the same class need not change these grouped estimates, while the exact raw-data statistics can change.</p>''',[
 ex('Unequal widths change the bar heights',table(['Class','Frequency'],[['0 ≤ x < 5',5],['5 ≤ x < 15',10],['15 ≤ x < 20',10]])+'<p>Find the three histogram heights.</p>',r'<p>The widths are 5, 10 and 5, so densities are 1, 1 and 2. The last two classes have the same frequency but different heights.</p>'+picture('histogram','A width-ten bar and a width-five bar have the same area but different heights'),'REP-DENSITY'),
 ex('A continuous boundary lies between rounded readings',r'<p>Lengths recorded to the nearest 0.1 cm are grouped from 2.0 through 2.9 cm. Give the continuous boundaries and width.</p>',r'\[1.95\le x<2.95,\qquad\text{width}=1.\]<p>The boundaries are half a recording unit beyond the first and last recorded values.</p>','REP-BOUNDARIES'),
 ex('Recover frequency from a plotted height',r'<p>A width-5 class has a bar 3 cm high. The vertical scale is 2 density units per centimetre. Find its frequency.</p>',r'\[\text{density}=3(2)=6,\qquad f=5(6)=30.\]<p>The plotted height must first be converted using the vertical scale.</p>','REP-SCALE'),
 ex('A midpoint calculation is an estimate',r'<p>Classes \([0,10),[10,20),[20,40)\) have frequencies 2, 4 and 4. Find the midpoint estimates of the mean and population variance.</p>',r'\[\sum f=10,\quad\sum fm=190,\quad\sum fm^2=4550.\]\[\bar{x}\approx19,\qquad\sigma^2\approx455-19^2=94.\]<p>The estimated SD is \(\sqrt{94}\). Actual within-class values need not have these exact statistics.</p>','REP-MIDPOINTS')])

lesson('cumulative','Cumulative frequency graphs, quartiles and percentiles',
 'Build cumulative totals at class boundaries and distinguish forward counts from inverse percentile readings.',
 r'''<h3>Plot cumulative counts at upper boundaries</h3><p>Begin at the first lower boundary with cumulative frequency zero. Add frequencies in order and plot at successive upper boundaries. The graph must not decrease. Join points with an appropriate increasing curve; a straight-line model is stated explicitly in the exact short checks.</p>'''+picture('cumulative','Cumulative totals plotted at upper boundaries')+r'''
 <h3>Read a quantile across, then down</h3><p>For N observations, read quartiles at cumulative levels \(N/4,N/2,3N/4\). A grouped graph gives estimates rather than exact ordered raw observations. For a stated straight-line segment,</p>\[x=L+\frac{r-C_{\rm before}}{f}\,w.\]<p>Here r is the target cumulative count, f the class frequency and w its width. Do not confuse cumulative frequency with class frequency.</p>
 <h3>A tail is a complement</h3><p>If C(a) is the estimated count below a, the estimated count above a is \(N-C(a)\). The count between a and b is \(C(b)-C(a)\), not the difference of the measurement values. Divide a count by N before converting to a percentage.</p>
 <h3>An inverse percentile starts with the frequency axis</h3><p>For the 80th percentile, locate \(0.8N\) first; 80 itself is generally neither the measurement nor the count. Reasonable readings of a carefully drawn freehand curve remain a matter for marking judgement in written questions.</p>''',[
 ex('Recover class frequencies from cumulative totals',table(['Boundary','Cumulative frequency'],[[0,0],[10,12],[20,28],[40,40]])+'<p>Give the three class frequencies.</p>',r'<p>Successive differences give 12, 16 and 12; the final cumulative total is 40. The middle cumulative value 28 is not the second class frequency.</p>','REP-CUM-DIFFERENCES'),
 ex('Interpolate a median on a stated straight segment',r'<p>Use the displayed cumulative points joined by straight segments. Estimate the median.</p>'+picture('cumulative','Straight segments between cumulative boundary points'),r'\[r=20,\qquad Q_2=10+\frac{20-12}{16}(10)=15.\]<p>The measurement lies halfway through the middle class in this model; it is not the twentieth raw observation read from a list.</p>','REP-CUM-MEDIAN'),
 ex('Convert the upper tail into a percentage',r'<p>For the same model, estimate the percentage above 30.</p>',r'<p>Between 20 and 40 the cumulative total rises from 28 to 40, so at 30 it is 34.</p>\[\frac{40-34}{40}(100)=15\%.\]','REP-CUM-TAIL'),
 ex('Invert a percentile reading',r'<p>For the same straight-line model, estimate the 80th percentile.</p>',r'\[r=0.8(40)=32,\qquad x=20+\frac{32-28}{12}(20)=\frac{80}{3}.\]<p>The result is a measurement estimate, about 26.7, not the cumulative count 32.</p>','REP-CUM-INVERSE')])

D=[2,4,5,7,8,11,13,16,25]
lesson('boxplots','Box-and-whisker plots, outliers and interpretation',
 'Find a complete five-number summary, follow the stated whisker rule and make defensible comparisons.',
 r'''<h3>A box shows the middle half</h3><p>The five-number summary is minimum, \(Q_1\), median, \(Q_3\), maximum. The box extends from \(Q_1\) to \(Q_3\); its internal line marks the median. Use one shared measurement scale when comparing samples.</p>'''+picture('boxplot','Five-number summary on a labelled horizontal scale')+r'''
 <h3>State both quartile and whisker conventions</h3><p>Raw quartiles here are medians of the halves, excluding an odd-sample overall median. Unless a question says otherwise, whiskers reach the minimum and maximum, including outliers. The rule must not silently change to a different boxplot convention.</p>
 <h3>Outlier fences identify unusual observations</h3>\[Q_1-1.5\mathrm{IQR},\qquad Q_3+1.5\mathrm{IQR}.\]<p>An observation strictly outside these fences is an outlier under this rule. A fence need not be an observed value and is not automatically a whisker endpoint.</p>
 <h3>Compare only what the diagram supports</h3><p>Compare medians and IQRs in context; use range if total spread is relevant. A boxplot does not determine the exact mean, every raw value, or prove a normal model. One written family uses later normal-model vocabulary and is clearly labelled as a later-topic application.</p>''',[
 ex('Locate five ordered landmarks','<p>Find a five-number summary for '+data(D)+', using the chapter convention.</p>',r'\[\min=2,\quad Q_1=4.5,\quad Q_2=8,\quad Q_3=14.5,\quad\max=25.\]<p>The overall median 8 is excluded from both halves. The IQR is 10.</p>'+picture('boxplot','A box from 4.5 to 14.5 with median 8 and whiskers 2 and 25'),'REP-BOX-SUMMARY'),
 ex('A fence is not a replacement observation',r'<p>Given \(Q_1=4,Q_3=12\), minimum 1 and maximum 30, identify outliers and whisker endpoints under the min/max convention.</p>',r'\[\mathrm{IQR}=8,\qquad\text{fences}=-8,24.\]<p>The value 30 is an outlier. Under the stated convention the whiskers still end at 1 and 30; neither fence is substituted as an observation.</p>','REP-OUTLIER'),
 ex('A higher median and a smaller IQR are separate facts',r'<p>A has median 18 and IQR 7; B has median 16 and IQR 11. The variable is completion time in minutes. Compare.</p>',r'<p>A has a higher typical completion time, so it typically took longer. Its middle half is less spread out, so those times were more consistent. It is possible to be more consistent while being slower.</p>','REP-BOX-COMPARE'),
 ex('Do not infer a missing mean',r'<p>A boxplot has five-number summary \((5,10,14,20,80)\). Can its exact mean be found? Which summary is resistant to the extreme upper value?</p>',r'<p>The five landmarks do not specify all observations, so the exact mean cannot be recovered. Median and IQR describe the centre and middle-half spread without being directly driven by the size of the extreme maximum. A normal model is not established by this summary.</p>','REP-BOX-INFERENCE')])

def field(key,label,kind,expected,**extra):return dict(key=key,label=label,type=kind,expected=str(expected),**extra)
def aset(a):return '{'+','.join(str(v) for v in a)+'}'
def show(f):
 if f['type']=='choice':return f['options'][f['expected']]
 if f['type']=='set':
  v=f['expected']
  if v.startswith('{'):return r'\(\{'+', '.join(tex(a) for a in v[1:-1].split(','))+r'\}\)'
  return r'\('+v[0]+', '.join(tex(a) for a in v[1:-1].split(','))+v[-1]+r'\)'
 return math(f['expected'])
def quick(topic,family,v,title,prompt,fields,explanation,model):
 uid=f'M4U-9709-S1-REP-CHECK-{topic.upper()}-{family}-{v}'
 answer=''.join('<p>'+f['label']+': '+show(f)+'</p>' for f in fields)
 questions.append(dict(id=uid,family_uid=f'M4U-9709-S1-REP-CHECK-{topic.upper()}-{family}',lesson=topic,title=title,collection='short' if v==0 else 'variant',prompt_html=prompt,answer_html=answer,solution_html='<p>'+explanation+'</p><h4>Complete answers</h4>'+answer,hint_html='<p>Read the key, units and convention; keep every observation and check whether the requested quantity is a count, measurement or estimate.</p>',marks=len(fields),difficulty=2,fields=fields,parts=[dict(label='',marking_criteria=[dict(code='B1',marks=1,description_html='Complete correct answer for '+f['label']+'.') for f in fields])],verification=uid))
 models.append(dict(uid=uid,**model))

def interp(xs,ys,z):
 for i in range(1,len(xs)):
  if z<=xs[i]:return F(ys[i-1])+F(z-xs[i-1],xs[i]-xs[i-1])*(ys[i]-ys[i-1])
 raise ValueError(z)

for v in range(2):
 scale=F(1) if v==0 else F(1,10);st,leaf=(12,7) if v==0 else (8,4);value=(st*10+leaf)*scale
 quick('stem_reading',1,v,'Decode the key and classify the variable',r'<p>A key says \(2\mid3\) represents '+math(format(float(23*scale),'g'))+(' orders. Interpret ' if v==0 else ' grams. Interpret ')+math(str(st)+r'\mid'+str(leaf))+'. Classify the underlying variable.</p>',
  [field('value','Decoded observation','number',value),field('type','Underlying variable','choice','A' if v==0 else 'C',options={'A':'Discrete quantitative','B':'Qualitative','C':'Continuous quantitative'})],'Use the scale in the key. Counts are discrete; mass is continuous even when rounded.',dict(kind='key',stem=st,leaf=leaf,scale=str(scale),choice='A' if v==0 else 'C'))
 a=[21,24,24,28,31,33,36] if v==0 else [32,35,35,39,42,44,47];wrong=a.copy();wrong[2]+=1;options={'A':stem(wrong),'B':stem(a),'C':stem(a[:-1])} if v==0 else {'A':stem(a[:-1]),'B':stem(wrong),'C':stem(a)}
 quick('stem_reading',2,v,'Choose the complete ordered diagram','<p>Choose the correct diagram for '+data(list(reversed(a)))+'. Retain repeats. Also give the total number of leaves.</p>',
  [field('diagram','Complete diagram','choice','B' if v==0 else 'C',options=options),field('count','Total leaves','number',len(a))],'Check the key, each row, the duplicate and the total leaf count. An omitted repeat changes the sample.',dict(kind='diagram',data=a,choice='B' if v==0 else 'C'))
 a=[11,13,14,16,18,20,22] if v==0 else [21,23,25,29,30,34,38];q=five(a)
 quick('stem_reading',3,v,'Read all quartiles and the IQR','<p>Using medians of halves and excluding the overall median, find the three quartiles and IQR.</p>'+stem(a),[field('q1','Lower quartile Q1','number',q[1]),field('median','Median Q2','number',q[2]),field('q3','Upper quartile Q3','number',q[3]),field('iqr','Interquartile range','number',q[3]-q[1])],'Order and count every leaf. Remove the overall median before finding the median of each remaining half.',dict(kind='quartiles',data=a))
 a=[21,23,25,28,31,35,36] if v==0 else [40,41,44,47,51,52,55];middle=a[3];display=stem(a).replace('5 8','5 a',1) if v==0 else stem(a).replace('0 1 4 7','0 1 4 a',1)
 quick('stem_reading',4,v,'An unknown leaf is a digit','<p>The diagram contains one unknown leaf a. The median is '+str(middle)+'. Find a, its complete observation and the IQR.</p>'+display,[field('leaf','Missing leaf a','number',middle%10),field('value','Complete missing observation','number',middle),field('iqr','Interquartile range','number',five(a)[3]-five(a)[1])],'The middle leaf determines one digit. Combine it with its stem before calculating numerical spread.',dict(kind='missing_leaf',data=a))

 a=[12+10*v,13+10*v,18+10*v,22+10*v,24+10*v,25+10*v,29+10*v];b=[13+10*v,16+10*v,20+10*v,23+10*v,27+10*v,30+10*v,31+10*v];fa,fb=five(a),five(b)
 quick('stem_comparison',1,v,'Read both sides before comparing','<p>Give the median and IQR for both routes, then select the supported comparison.</p>'+stem(a,b,names=('Route A','Route B'),unit='minutes'),[field('ma','Median A','number',fa[2]),field('mb','Median B','number',fb[2]),field('ia','IQR A','number',fa[3]-fa[1]),field('ib','IQR B','number',fb[3]-fb[1]),field('comparison','Supported comparison','choice','B',options={'A':'A is slower and less consistent','B':'A has a lower median time and smaller IQR','C':'Both samples have the same spread'})],'Read the left leaves from the stem outwards. Compare the named medians and IQRs, not the visual lengths of one row.',dict(kind='back',a=a,b=b))
 a=[8+5*v,10+5*v,11+5*v,15+5*v];mean=12+5*v;missing=5*mean-sum(a);complete=a+[missing]
 quick('stem_comparison',2,v,'A new observation changes the denominator','<p>The values '+data(a)+' are followed by one omitted value. The final mean of all five is '+str(mean)+'. Find the omitted value and final median.</p>',[field('missing','Omitted observation','number',missing),field('median','Median after inclusion','number',F(median(complete)))],r'Use total \(=5\bar{x}\), subtract the four known observations, then order all five.',dict(kind='missing_mean',data=a,mean=mean))
 a=[10+v,12+v,16+v,20+v,40+v];b=[9+v,14+v,18+v,22+v,30+v]
 quick('stem_comparison',3,v,'Equal central spread can hide different extremes','<p>Five-number summaries are A: '+data(a)+'; B: '+data(b)+'. Find both ranges and choose a justified central comparison.</p>',[field('ra','Range A','number',a[4]-a[0]),field('rb','Range B','number',b[4]-b[0]),field('comparison','Supported comparison','choice','C',options={'A':'A must have a smaller mean','B':'The two full ranges are equal','C':'A has a lower median; the IQRs are equal'})],'The range uses the extremes; IQR uses only Q1 and Q3. These summaries do not determine the means.',dict(kind='summary_comparison',a=a,b=b))
 na,ma,sa,nb,mb,sb=(3,10,2,2,15,3) if v==0 else (4,8,3,2,14,1);n=na+nb;mean=F(na*ma+nb*mb,n);variance=F(na*(sa*sa+ma*ma)+nb*(sb*sb+mb*mb),n)-mean*mean
 quick('stem_comparison',4,v,'Combine first and second moments',f'<p>Mixed-topic check. Sample A has n={na}, mean {ma}, population SD {sa}; B has n={nb}, mean {mb}, population SD {sb}. Find the combined mean, variance and SD exactly. Use divisor n.</p>',[field('mean','Combined mean','number',mean),field('variance','Combined population variance','number',variance),field('sd','Combined population SD','number',s.sqrt(s.Rational(variance.numerator,variance.denominator)))],'Reconstruct both sums and sums of squares. Divide the combined totals by the combined count before subtracting the squared combined mean.',dict(kind='pooled',na=na,ma=ma,sa=sa,nb=nb,mb=mb,sb=sb))

 edges=[0,10,30,40];freq=[4,12,8] if v==0 else [6,8,10];dens=[F(freq[i],edges[i+1]-edges[i]) for i in range(3)]
 quick('histograms',1,v,'Height and frequency need not select the same class',table(['Class','Frequency'],[[f'{edges[i]} ≤ x < {edges[i+1]}',freq[i]] for i in range(3)])+'<p>Give all three frequency densities and select the class with the greatest frequency.</p>',[field('d1','First density','number',dens[0]),field('d2','Second density','number',dens[1]),field('d3','Third density','number',dens[2]),field('modal','Greatest-frequency class','choice','B' if v==0 else 'C',options={'A':'0 ≤ x < 10','B':'10 ≤ x < 30','C':'30 ≤ x < 40'})],'Divide by each actual width. Select the greatest frequency from bar area, not merely from the tallest density.',dict(kind='density',edges=edges,freq=freq))
 width,height,scale,otherwidth,otherfreq=(5,4,3,10,30) if v==0 else (4,3,2,8,32)
 quick('histograms',2,v,'Recover counts from a physical bar scale',f'<p>A class of width {width} has a histogram bar {height} cm high. Each vertical centimetre represents {scale} density units. Another class has width {otherwidth} and frequency {otherfreq}. Give the first density, first frequency and second physical height.</p>',[field('density','First frequency density','number',height*scale),field('frequency','First frequency','number',width*height*scale),field('height','Second height in cm','number',F(otherfreq,otherwidth*scale))],'Convert centimetres to density before multiplying by width. Reverse those steps for the other bar.',dict(kind='scale',width=width,height=height,scale=scale,otherwidth=otherwidth,otherfreq=otherfreq))
 lo,hi,step=(F(20),F(29),F(1)) if v==0 else (F(3),F(34,10),F(1,10));lower,upper=lo-step/2,hi+step/2
 quick('histograms',3,v,'Rounding fixes the continuous boundaries','<p>Positive lengths rounded half-up to the nearest '+math(step)+' are grouped from recorded value '+math(lo)+' through '+math(hi)+r'. Give the continuous class interval, including endpoint brackets, and its width.</p>',[field('interval','Continuous class interval','set','['+str(lower)+','+str(upper)+')'),field('width','Continuous class width','number',upper-lower)],'Adjust by half one recording unit at each end. The upper tie belongs to the following recorded class.',dict(kind='rounding',lo=str(lo),hi=str(hi),step=str(step)))
 edges=[0,10,20,40];freq=[2,4,4] if v==0 else [4,2,4];mid=[F(edges[i]+edges[i+1],2) for i in range(3)];n=sum(freq);mean=sum(f*m for f,m in zip(freq,mid))/n;variance=sum(f*m*m for f,m in zip(freq,mid))/n-mean*mean
 quick('histograms',4,v,'Keep the midpoint model separate from raw statistics',table(['Class','Frequency'],[[f'{edges[i]} ≤ x < {edges[i+1]}',freq[i]] for i in range(3)])+'<p>Using class midpoints, give the mean, population variance and SD exactly for this midpoint model. These are estimates for the original raw data.</p>',[field('mean','Midpoint mean','number',mean),field('variance','Midpoint variance','number',variance),field('sd','Midpoint SD','number',s.sqrt(s.Rational(variance.numerator,variance.denominator)))],'Use the weighted midpoints, square each midpoint for the second moment, and use the same total frequency in both terms.',dict(kind='grouped_moments',edges=edges,freq=freq))

 edges=[0,10,20,40];cum=[0,10,30,40] if v==0 else [0,8,24,40];n=cum[-1];shown=table(['Upper boundary','Cumulative count'],list(zip(edges,cum)));convention='<p>Use straight segments between these cumulative points for all interpolated values.</p>'
 quick('cumulative',1,v,'Recover all class frequencies',shown+'<p>Give the frequencies of the three successive classes.</p>',[field('f'+str(i),'Frequency of class '+str(i),'number',cum[i]-cum[i-1]) for i in range(1,4)],'Subtract each previous cumulative count from the next; the final cumulative count is the total.',dict(kind='cumulative_frequencies',edges=edges,cum=cum))
 q=[interp(cum,edges,F(n*j,4)) for j in (1,2,3)]
 quick('cumulative',2,v,'Read the three quartiles and their spread',shown+convention+'<p>Give Q1, median, Q3 and IQR exactly under this straight-line model.</p>',[field('q1','Lower quartile estimate','number',q[0]),field('median','Median estimate','number',q[1]),field('q3','Upper quartile estimate','number',q[2]),field('iqr','IQR estimate','number',q[2]-q[0])],'Locate the frequency levels N/4, N/2 and 3N/4, then interpolate x. These are grouped-model readings, not exact raw order statistics.',dict(kind='cumulative_quartiles',edges=edges,cum=cum))
 c15=interp(edges,cum,15);c30=interp(edges,cum,30)
 quick('cumulative',3,v,'Upper tails and intervals are count differences',shown+convention+'<p>Estimate the count above 15, the count between 15 and 30 and the percentage above 15.</p>',[field('above','Count above 15','number',n-c15),field('between','Count between 15 and 30','number',c30-c15),field('percent','Percentage above 15, without %','number',100*(n-c15)/n)],'The upper tail is the total minus the cumulative count. An interval uses two cumulative counts before converting any requested proportion to a percentage.',dict(kind='cumulative_tail',edges=edges,cum=cum))
 p80=interp(cum,edges,F(4*n,5));p90=interp(cum,edges,F(9*n,10))
 quick('cumulative',4,v,'Invert a percentile rather than reading it as x',shown+convention+'<p>Give the 80th and 90th percentile estimates exactly. Select the correct starting step.</p>',[field('p80','80th percentile estimate','number',p80),field('p90','90th percentile estimate','number',p90),field('method','Starting step for the 80th percentile','choice','A' if v==0 else 'C',options={'A':'Locate cumulative frequency 0.8N, then read x','B':'Use x = 80','C':'Take 80% of the largest measurement'} if v==0 else {'A':'Read the cumulative count at x = 80','B':'Use the 80th observation regardless of N','C':'Locate cumulative frequency 0.8N, then read x'})],'A percentile is a measurement at a specified fraction of the cumulative count.',dict(kind='percentiles',edges=edges,cum=cum))

 a=[4+3*v,5+3*v,7+3*v,8+3*v,9+3*v,11+3*v,13+3*v,15+3*v,20+3*v];f=five(a)
 quick('boxplots',1,v,'A complete five-number summary','<p>Find the complete five-number summary for '+data(a)+'. Use medians of halves, excluding the overall median.</p>',[field(k,label,'number',value) for k,label,value in zip(['min','q1','median','q3','max'],['Minimum','Lower quartile Q1','Median Q2','Upper quartile Q3','Maximum'],f)],'Split the sorted data after identifying and excluding the middle observation. Give both extremes as well as the three quartiles.',dict(kind='five',data=a))
 q1,q3,low,high=(10,18,2,35) if v==0 else (12,22,4,40);iq=q3-q1;lf,hf=F(q1)-F(3,2)*iq,F(q3)+F(3,2)*iq
 quick('boxplots',2,v,'Outlier fences do not silently change the whiskers',f'<p>A sample has Q1={q1}, Q3={q3}, minimum {low}, maximum {high}. Only the maximum lies outside the 1.5 IQR fences. Give both fences and both whisker endpoints under the stated min/max convention.</p>',[field('lower','Lower outlier fence','number',lf),field('upper','Upper outlier fence','number',hf),field('whiskers','Both whisker endpoints','set',aset([low,high]))],'A fence is a calculated threshold. Under this explicitly stated convention, the whiskers still use the observed minimum and maximum, including the outlier.',dict(kind='fences',q1=q1,q3=q3,low=low,high=high))
 a,b=([1,4,7,12,20],[0,5,9,11,24]) if v==0 else ([2,6,10,16,25],[4,7,9,11,30])
 quick('boxplots',3,v,'Compare centre and central spread separately','<p>Five-number summaries are A: '+data(a)+'; B: '+data(b)+'. Give both IQRs and select a supported comparison.</p>',[field('ia','IQR A','number',a[3]-a[1]),field('ib','IQR B','number',b[3]-b[1]),field('comparison','Supported comparison','choice','B' if v==0 else 'C',options={'A':'A has the smaller IQR','B':'B has the higher median and smaller IQR','C':'A must have the larger mean'} if v==0 else {'A':'B has the higher median','B':'A is more consistent by IQR','C':'A has the higher median; B has the smaller IQR'})],'Median compares centre; IQR compares the middle half. A large extreme does not determine either mean.',dict(kind='box_comparison',a=a,b=b))
 a=[5+v,10+v,14+v,20+v,80+10*v]
 quick('boxplots',4,v,'A boxplot cannot supply a missing mean','<p>A boxplot has five-number summary '+data(a)+'. Give the IQR, choose a resistant summary and state whether its exact mean is determined.</p>',[field('iqr','Interquartile range','number',a[3]-a[1]),field('summary','Resistant centre and spread','choice','B',options={'A':'Mean and range','B':'Median and IQR','C':'Maximum and range'}),field('mean','Is the exact mean determined?','choice','C',options={'A':'Yes: average the five landmarks','B':'Yes: it equals the median','C':'No: the individual observations are not all specified'})],'A five-number summary leaves many possible raw datasets. The median and IQR are less directly affected by an extreme maximum.',dict(kind='inference',summary=a))
